head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > collapsible]<br/>열려 있는 패널의 타이틀을 클릭하여 패널을 닫을 수 있게 할지 설정합니다.",
    "validation" : [
        "collapsible=true 설정 시 열려 있는 패널의 타이틀 클릭 시 해당 패널을 닫습니다.",
        "collapsible=true 설정 시 닫혀 있는 패널의 타이틀 클릭 시 다른 열린 패널을 모두 닫고 클릭한 패널만 엽니다.",
        "collapsible=false (default) 설정 시 열려 있는 패널의 타이틀 클릭 시 해당 패널을 닫지 않고 열린 상태를 유지합니다.",
        "collapsible=false (default) 설정 시 닫혀 있는 패널의 타이틀 클릭 시 다른 열린 패널을 모두 닫고 클릭한 패널만 엽니다.",
        "collapsible 속성값에 따라 openPanel() 메소드의 동작이 타이틀 클릭 동작과 반대 패턴으로 작동합니다.",
        "collapsible=false 일 때 타이틀 클릭은 다른 패널을 닫고 대상 패널을 열지만, openPanel() 메소드는 다른 패널을 닫지 않고 대상 패널만 엽니다.",
        "collapsible=true 일 때 타이틀 클릭은 다른 패널에 영향을 주지 않고 대상 패널만 토글하지만, openPanel() 메소드는 다른 열린 패널을 닫고 대상 패널을 엽니다.",
        "closePanel() 메소드는 collapsible 속성값에 관계없이 지정한 패널을 닫습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        collapsible : con_collapsible.getText(),        
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* collapsible=true : 타이틀 클릭 시 다른 패널 영향 없이 클릭 패널만 토글, 모든 패널 닫힘 허용"', '', 'label1');
    $c.gcm.createLabel('label="* collapsible=false : 타이틀 클릭 시 다른 열린 패널 모두 닫고 클릭 패널만 열림, 이미 열린 패널 재클릭 시 닫히지 않음"', '', 'label2');
    $c.gcm.createLabel('label="* openPanel() / closePanel() 은 타이틀 클릭과 반대 패턴 / closePanel 은 collapsible 무관 동작"', '', 'label3');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// 현재 열린 패널 정보 출력
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};



// openPanel(par_panelId) 호출 — @spec : 타이틀 클릭 반대 패턴
scwin.btn_openPanel_onclick = function (e) {
    let panelId = par_panelId.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("===== openPanel('" + panelId + "') 호출 =====");
    target1.openPanel(panelId);
};



// closePanel(par_panelId) 호출 — @spec : collapsible 값 무관 동작
scwin.btn_closePanel_onclick = function (e) {
    let panelId = par_panelId.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("===== closePanel('" + panelId + "') 호출 =====");
    target1.closePanel(panelId);
};
